import { useEffect, useState } from 'react';
import {
  JxBadge,
  JxDivider,
  JxSelect,
  JxSlider,
  JxSwitch,
  JxToggle,
} from '@jinx-ui/react';

export interface AppearanceSettings {
  theme: 'light' | 'dark' | 'system';
  scale: number;
  compact: boolean;
  fontFamily: string;
}

interface AppearanceSettingsScreenProps {
  onChange?: (settings: AppearanceSettings) => void;
}

const themeLabels: Record<AppearanceSettings['theme'], string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

export default function AppearanceSettingsScreen({ onChange }: AppearanceSettingsScreenProps) {
  const [theme, setTheme] = useState<AppearanceSettings['theme']>('system');
  const [scale, setScale] = useState(100);
  const [compact, setCompact] = useState(false);
  const [fontFamily, setFontFamily] = useState('sans');

  useEffect(() => {
    onChange?.({ theme, scale, compact, fontFamily });
  }, [theme, scale, compact, fontFamily, onChange]);

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 24,
        maxWidth: 480,
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 12,
        }}
      >
        <h1
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: 22,
            color: 'var(--jx-text)',
          }}
        >
          Внешний вид
        </h1>
        <JxBadge tone="accent">{themeLabels[theme]}</JxBadge>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        <span style={{ fontSize: 14, color: 'var(--jx-text-2)' }}>Тема</span>
        <JxToggle
          items={[
            { value: 'light', label: 'Светлая' },
            { value: 'dark', label: 'Тёмная' },
            { value: 'system', label: 'Системная' },
          ]}
          value={theme}
          onValueChange={(value) => setTheme(value as AppearanceSettings['theme'])}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        unit="%"
        showOutput
        value={scale}
        onValueChange={setScale}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={compact}
        onChange={(event) => setCompact(event.target.checked)}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт интерфейса"
        options={[
          { value: 'sans', label: 'Sans (по умолчанию)' },
          { value: 'display', label: 'Display' },
          { value: 'mono', label: 'Моноширинный' },
        ]}
        value={fontFamily}
        onValueChange={setFontFamily}
      />
    </div>
  );
}

